// SPDX-License-Identifier: Apache-2.0
//! ADR atoms and their lifecycle (SAS §19).
//!
//! §4.3: "**ADR** continues to mean **Architecture Decision Record**.
//! OpenWarrant SHALL NOT redefine ADR." Every normative decision is a
//! first-class record with its own identity, lifecycle, and source atom.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::frontmatter::{self, FrontmatterError};

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum AdrError {
    #[error("frontmatter: {0}")]
    Frontmatter(#[from] FrontmatterError),
    #[error("missing required frontmatter key {key:?}")]
    MissingKey { key: &'static str },
    #[error(
        "unknown ADR status {found:?}; expected one of \
         proposed, accepted, superseded, deprecated, rejected, withdrawn, falsified"
    )]
    UnknownStatus { found: String },
}

/// Where an ADR sits in its lifecycle.
///
/// `Falsified` is a first-class terminal state, not a synonym for rejected. A
/// decision whose claim was disproved by measurement is a RESULT — the record
/// keeps the measurement that disproved it — whereas rejected means never
/// accepted in the first place. Collapsing them would lose the distinction
/// between "we tried it and it did not hold" and "we declined to try it".
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AdrStatus {
    Proposed,
    Accepted,
    Superseded,
    Deprecated,
    Rejected,
    Withdrawn,
    Falsified,
}

impl AdrStatus {
    pub const ALL: [Self; 7] = [
        Self::Proposed,
        Self::Accepted,
        Self::Superseded,
        Self::Deprecated,
        Self::Rejected,
        Self::Withdrawn,
        Self::Falsified,
    ];

    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Proposed => "proposed",
            Self::Accepted => "accepted",
            Self::Superseded => "superseded",
            Self::Deprecated => "deprecated",
            Self::Rejected => "rejected",
            Self::Withdrawn => "withdrawn",
            Self::Falsified => "falsified",
        }
    }

    /// Whether this decision still governs new work (§24.4 currency).
    #[must_use]
    pub const fn is_current(self) -> bool {
        match self {
            Self::Accepted => true,
            // Proposed is NOT current: a proposed ADR cannot satisfy an
            // accepted-decision prerequisite (§91.4 test 28).
            Self::Proposed
            | Self::Superseded
            | Self::Deprecated
            | Self::Rejected
            | Self::Withdrawn
            | Self::Falsified => false,
        }
    }

    /// The Appendix A section this status is listed under.
    #[must_use]
    pub const fn overview_section(self) -> &'static str {
        match self {
            Self::Proposed => "Proposed",
            Self::Accepted => "Accepted and Current",
            Self::Superseded | Self::Deprecated => "Superseded",
            Self::Rejected | Self::Withdrawn | Self::Falsified => {
                "Rejected, Withdrawn, or Falsified"
            }
        }
    }
}

impl FromStr for AdrStatus {
    type Err = AdrError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Self::ALL
            .into_iter()
            .find(|status| status.as_str() == s)
            .ok_or_else(|| AdrError::UnknownStatus {
                found: s.to_owned(),
            })
    }
}

impl fmt::Display for AdrStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// One ADR, parsed from its source atom.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AdrRecord {
    pub uuid: String,
    pub local_alias: String,
    pub title: String,
    pub status: AdrStatus,
    pub decided: Option<String>,
    /// Warrants this decision governs (§19.4).
    pub governs: Vec<String>,
    /// Decisions this one supersedes (`adr://…`), from front matter (§19.3).
    pub supersedes: Vec<String>,
    /// The decision that superseded this one, if any (§19.3, §24.4).
    pub superseded_by: Option<String>,
    /// The atom body, frontmatter stripped.
    pub body: String,
    /// Repository-relative source path.
    pub source: String,
}

impl AdrRecord {
    /// Parse an ADR atom.
    ///
    /// The title is taken from the body's first `#` heading rather than from a
    /// frontmatter field, so there is exactly one place a title can live and it
    /// is the place a human reads. A separate `title:` key would be a second
    /// source that could disagree with the heading.
    pub fn parse(source: &str, text: &str) -> Result<Self, AdrError> {
        let fm = frontmatter::parse(text)?;
        let get = |key: &'static str| -> Result<String, AdrError> {
            fm.scalar(key)
                .map(str::to_owned)
                .ok_or(AdrError::MissingKey { key })
        };

        let body = text[fm.body_offset..].trim_start_matches('\n').to_owned();
        let title = body
            .lines()
            .find(|line| line.starts_with("# "))
            .map(|line| line.trim_start_matches("# ").trim().to_owned())
            .unwrap_or_else(|| "(untitled)".to_owned());

        Ok(Self {
            uuid: get("adr_uuid")?,
            local_alias: get("local_alias")?,
            title,
            status: AdrStatus::from_str(&get("status")?)?,
            decided: fm.scalar("decided").map(str::to_owned),
            governs: fm.list("governs").unwrap_or_default().to_vec(),
            supersedes: fm.list("supersedes").unwrap_or_default().to_vec(),
            superseded_by: fm.scalar("superseded_by").map(str::to_owned),
            body,
            source: source.to_owned(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "---\n\
schema: oh.war/atom/v1\n\
adr_uuid: 01a01927-8855-7046-9876-ef13ae754180\n\
local_alias: OW-ADR-0001\n\
role: adr\n\
jurisdiction: bound\n\
status: accepted\n\
decided: 2026-08-19\n\
governs:\n  - \"war://01a0-abc\"\n\
---\n\n# ADR OW-0001: Adopt something\n\n## Status\n\nAccepted.\n";

    /// §19.3 — supersession is a relation between decisions, read from front
    /// matter, in both directions (OW-WAR-0006 OBL-001).
    #[test]
    fn supersession_relations_are_read_in_both_directions() {
        let text = SAMPLE.replace(
            "governs:\n",
            "supersedes:\n  - \"adr://01a0-old\"\nsuperseded_by: \"adr://01a0-newer\"\ngoverns:\n",
        );
        let adr = AdrRecord::parse("x.md", &text).expect("parses");
        assert_eq!(adr.supersedes, vec!["adr://01a0-old"]);
        assert_eq!(adr.superseded_by.as_deref(), Some("adr://01a0-newer"));
        let plain = AdrRecord::parse("x.md", SAMPLE).expect("parses");
        assert!(plain.supersedes.is_empty() && plain.superseded_by.is_none());
    }

    #[test]
    fn parses_an_adr_atom() {
        let adr = AdrRecord::parse("docs/adr/atoms/x.md", SAMPLE).expect("parses");
        assert_eq!(adr.local_alias, "OW-ADR-0001");
        assert_eq!(adr.status, AdrStatus::Accepted);
        assert_eq!(adr.decided.as_deref(), Some("2026-08-19"));
        assert_eq!(adr.governs, vec!["war://01a0-abc"]);
        assert_eq!(adr.title, "ADR OW-0001: Adopt something");
        assert!(adr.body.starts_with("# ADR OW-0001"));
        assert!(
            !adr.body.contains("schema:"),
            "frontmatter must be stripped"
        );
    }

    #[test]
    fn missing_required_keys_fail_closed() {
        let without_status = SAMPLE.replace("status: accepted\n", "");
        assert_eq!(
            AdrRecord::parse("x", &without_status),
            Err(AdrError::MissingKey { key: "status" })
        );
        let without_uuid = SAMPLE.replace("adr_uuid: 01a01927-8855-7046-9876-ef13ae754180\n", "");
        assert_eq!(
            AdrRecord::parse("x", &without_uuid),
            Err(AdrError::MissingKey { key: "adr_uuid" })
        );
    }

    #[test]
    fn unknown_status_is_refused() {
        let bad = SAMPLE.replace("status: accepted", "status: probably-fine");
        assert_eq!(
            AdrRecord::parse("x", &bad),
            Err(AdrError::UnknownStatus {
                found: "probably-fine".to_owned()
            })
        );
    }

    /// §91.4 test 28: a proposed ADR cannot satisfy an accepted-decision
    /// prerequisite, so it is not current.
    #[test]
    fn only_accepted_is_current() {
        assert!(AdrStatus::Accepted.is_current());
        for status in AdrStatus::ALL.iter().filter(|s| **s != AdrStatus::Accepted) {
            assert!(!status.is_current(), "{status} must not be current");
        }
    }

    /// Falsified is its own terminal state, distinct from rejected.
    #[test]
    fn falsified_and_rejected_are_distinct() {
        assert_ne!(AdrStatus::Falsified, AdrStatus::Rejected);
        assert_eq!(
            AdrStatus::Falsified.overview_section(),
            AdrStatus::Rejected.overview_section(),
            "they share a section but not an identity"
        );
    }

    #[test]
    fn every_status_maps_to_an_appendix_a_section() {
        let sections = [
            "Proposed",
            "Accepted and Current",
            "Superseded",
            "Rejected, Withdrawn, or Falsified",
        ];
        for status in AdrStatus::ALL {
            assert!(
                sections.contains(&status.overview_section()),
                "{status} maps to an unknown section"
            );
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! ADR relations and currency (SAS §19.2, §19.4, §21), read projections
//! (§17.5), telemetry (§94), and untracked-work detection (§95).
//! RQ-020, RQ-024, RQ-025, RQ-073.
//!
//! # Nothing is silently carried forward
//!
//! §21.5: *"A superseding WAR SHALL explicitly identify which unresolved child
//! WARs, deliverables, evidence, or obligations it adopts. Nothing is silently
//! carried forward."*
//!
//! [`Supersession::validate`] takes the list of unresolved items and refuses a
//! supersession that leaves any of them unaddressed. Every item is either
//! **adopted** or **explicitly dropped with a reason** — there is no third
//! option, because the third option is the silence §21.5 forbids.
//!
//! §21.4 pairs with it: *"Superseded and deprecated WARs SHALL remain available
//! for audit and relation traversal."* Supersession changes currency; it removes
//! nothing.
//!
//! # A decision is an ADR when a future reader would need the reason
//!
//! §19.2 lists six things that do NOT need an ADR, then gives the test:
//!
//! > Would a future executor need to know why one alternative was chosen over
//! > another, or would this choice constrain future work?
//!
//! [`needs_adr`] applies that test, and — like [`crate::autonomy::classify`] —
//! returns `Unknown` rather than guessing. §19.2's exemptions are a closed list;
//! anything outside it has not been shown to be exempt, and the safe direction
//! for an unrecognised decision is to ask.
//!
//! # §95 is a signal, not an accusation
//!
//! *"This is a diagnostic and governance signal. It SHALL not fabricate a
//! relationship after the fact without review."* [`UntrackedWork`] produces
//! candidates, and [`UntrackedWork::attach_relation`] refuses without a recorded
//! reviewer.

use std::collections::BTreeSet;

use serde::{Deserialize, Serialize};

use crate::vocab::vocabulary;

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum LifecycleError {
    #[error("unknown {vocabulary} {found:?}; SAS defines {known}")]
    UnknownTerm {
        vocabulary: &'static str,
        found: String,
        known: String,
    },
    #[error(
        "supersession of {superseded:?} leaves {count} unresolved item(s) \
         unaddressed: {items}. §21.5 — a superseding WAR SHALL explicitly identify \
         what it adopts, and nothing is silently carried forward"
    )]
    SilentCarryForward {
        superseded: String,
        count: usize,
        items: String,
    },
    #[error(
        "supersession of {superseded:?} drops {item:?} without a reason. Dropping is \
         a legitimate choice and an unexplained drop is the same silence §21.5 \
         forbids, one step later"
    )]
    DropWithoutReason { superseded: String, item: String },
    #[error("supersession of {superseded:?} states no reason (§21.1)")]
    SupersessionWithoutReason { superseded: String },
    #[error(
        "a Warrant with currency {currency} was deleted or made unavailable. §21.4: \
         superseded and deprecated WARs SHALL remain available for audit and \
         relation traversal"
    )]
    RetiredWarrantRemoved { currency: Currency },
    #[error(
        "untracked-work candidate {scope:?} was related to {warrant:?} with no \
         recorded reviewer. §95: this SHALL not fabricate a relationship after the \
         fact without review"
    )]
    RelationFabricated { scope: String, warrant: String },
    #[error("telemetry omits {measure:?}, which §94 requires the system to measure")]
    TelemetryIncomplete { measure: &'static str },
}

vocabulary!(
    /// §21's currency values.
    Currency, "currency", LifecycleError, {
        Current => "current",
        Superseded => "superseded",
        Deprecated => "deprecated",
    }
);

impl Currency {
    /// §21.2 and §21.3 — retired for new execution, still authoritative for what
    /// it described.
    #[must_use]
    pub const fn retired_for_new_execution(self) -> bool {
        matches!(self, Self::Superseded | Self::Deprecated)
    }

    /// §21.4 — retired is never removed.
    #[must_use]
    pub const fn remains_available(self) -> bool {
        true
    }

    /// §21.2's required banner, verbatim.
    #[must_use]
    pub const fn banner(self) -> Option<&'static str> {
        match self {
            Self::Superseded => Some(
                "**Superseded and deprecated for new execution. See WAR X. \
                 Historical artifacts, evidence, and resolution remain authoritative \
                 for the period and basis they describe.**",
            ),
            Self::Deprecated | Self::Current => None,
        }
    }
}

vocabulary!(
    /// §19.4's ADR relations to a Warrant.
    AdrRelation, "ADR relation", LifecycleError, {
        OriginatesFrom => "originates_from",
        Governs => "governs",
        ImplementedBy => "implemented_by",
        Supersedes => "supersedes",
        AmendsSas => "amends_sas",
        AuthorizesAmendmentClass => "authorizes_amendment_class",
        RecordsPhaseGateOutcome => "records_phase_gate_outcome",
    }
);

vocabulary!(
    /// §17.5's read projections.
    Projection, "projection", LifecycleError, {
        FullWarrant => "full_warrant",
        WorkOrder => "work_order",
        AdrSection => "adr_section",
        AdrOverview => "adr_overview",
        StageDispatch => "stage_dispatch",
        AssuranceCase => "assurance_case",
        Status => "status",
        Audit => "audit",
        CanonicalJson => "canonical_json",
    }
);

/// §19.2's six exemptions, verbatim.
pub const NOT_A_NEW_ADR: [&str; 6] = [
    "a private variable name",
    "a local refactor preserving all declared behavior",
    "selection among equivalent permitted tools",
    "a mechanical application of a governing ADR",
    "an auto-authorized amendment class whose governing policy already made the normative decision",
    "a factual correction with no semantic choice",
];

/// The answer to §19.2's test.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AdrNeed {
    /// §19.2 exempts it explicitly.
    Exempt,
    /// A future executor would need the reason, or it constrains future work.
    Required,
    /// Neither exempt nor obviously normative. Ask.
    Unknown,
}

/// §19.2's test, applied.
///
/// `constrains_future_work` and `future_reader_needs_the_reason` come from the
/// author, not from this function — §19.2 asks a question about consequences,
/// and no string match can answer it. What this does is refuse to guess: a
/// decision that is neither on the exemption list nor declared constraining
/// returns `Unknown`, and the safe response to `Unknown` is to ask.
#[must_use]
pub fn needs_adr(
    decision: &str,
    constrains_future_work: bool,
    future_reader_needs_the_reason: bool,
) -> AdrNeed {
    if constrains_future_work || future_reader_needs_the_reason {
        // The test in §19.2 is decisive in this direction even for an item that
        // resembles an exemption: "if yes, create an ADR".
        return AdrNeed::Required;
    }
    let d = decision.trim().to_lowercase();
    if NOT_A_NEW_ADR.iter().any(|e| *e == d) {
        return AdrNeed::Exempt;
    }
    AdrNeed::Unknown
}

/// What a superseding Warrant does with one unresolved item (§21.5).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Adoption {
    pub item: String,
    pub adopted: bool,
    /// Required when `adopted` is false. An unexplained drop is the same silence
    /// §21.5 forbids, one step later.
    #[serde(default)]
    pub drop_reason: String,
}

/// §21.1's supersession relation.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
pub struct Supersession {
    pub superseding: String,
    pub superseded: String,
    pub reason: String,
    #[serde(default)]
    pub adoptions: Vec<Adoption>,
}

impl Supersession {
    /// §21.1 and §21.5.
    ///
    /// `unresolved` is the superseded Warrant's actual unresolved items, so the
    /// superseding Warrant cannot satisfy this by listing only what it felt like
    /// addressing.
    pub fn validate(&self, unresolved: &[String]) -> Result<(), LifecycleError> {
        if self.reason.trim().is_empty() {
            return Err(LifecycleError::SupersessionWithoutReason {
                superseded: self.superseded.clone(),
            });
        }
        let addressed: BTreeSet<&str> = self.adoptions.iter().map(|a| a.item.as_str()).collect();
        let missing: Vec<&str> = unresolved
            .iter()
            .map(String::as_str)
            .filter(|i| !addressed.contains(i))
            .collect();
        if !missing.is_empty() {
            return Err(LifecycleError::SilentCarryForward {
                superseded: self.superseded.clone(),
                count: missing.len(),
                items: missing.join(", "),
            });
        }
        for a in &self.adoptions {
            if !a.adopted && a.drop_reason.trim().is_empty() {
                return Err(LifecycleError::DropWithoutReason {
                    superseded: self.superseded.clone(),
                    item: a.item.clone(),
                });
            }
        }
        Ok(())
    }

    /// §21.2 — what the superseded Warrant's currency becomes.
    #[must_use]
    pub const fn superseded_currency() -> Currency {
        Currency::Superseded
    }
}

/// §94's measures, verbatim.
pub const TELEMETRY_MEASURES: [&str; 20] = [
    "human authoring minutes",
    "interview questions",
    "clarification count",
    "escalation count and class",
    "amendments",
    "auto-authorizable fraction",
    "replay, repair, restart",
    "gate failure cause",
    "adequacy counterexamples",
    "wall time",
    "compute and model cost",
    "context tokens per dispatch",
    "context tokens per verification",
    "time to first usable artifact",
    "reopenings",
    "untracked commits or artifacts",
    "work completed outside WAR",
    "evidence and gate reuse",
    "post-resolution escapes",
    "gate library reuse",
];

/// §94's derived metrics, verbatim.
pub const DERIVED_METRICS: [&str; 8] = [
    "human control minutes per accepted WAR",
    "amendments per WAR",
    "safe auto-amendment fraction",
    "gate-failure-to-repair success rate",
    "post-resolution escape rate",
    "untracked-work rate",
    "adequacy-review catch rate",
    "gate-library reuse rate",
